void palindrome(char *s,int l)
{
    int count=0;
    for(int i=0;i<((l)/2);i++)
    {
        if(*(s+i)!=*(s+l-i))
        {
            count=1;
            break;
        }
    }
    if(count==0)
    printf("Yes");
